<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);$action=$_POST['action']??'';if($action==='save'){try{db()->prepare('INSERT INTO categories(user_id,name,type,is_default,is_active) VALUES(NULL,?,?,TRUE,TRUE)')->execute([trim($_POST['name']),$_POST['type']]);flash('success','Default category added.');}catch(Throwable$e){flash('error','Category already exists.');}}elseif($action==='toggle')db()->prepare('UPDATE categories SET is_active=IF(is_active=1,0,1) WHERE category_id=? AND is_default=1')->execute([(int)$_POST['category_id']]);redirect('admin/categories.php');}$rows=db()->query('SELECT c.*,COUNT(t.transaction_id) usage_count FROM categories c LEFT JOIN transactions t ON t.category_id=c.category_id WHERE c.is_default=1 GROUP BY c.category_id ORDER BY c.type,c.name')->fetchAll();$pageTitle='Categories';$activePage='categories';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">SYSTEM CONTENT</span><h1>Default categories</h1><p>Shared categories for all students.</p></div></section><div class="two-column"><section class="panel"><div class="panel-head"><div><span class="panel-kicker">CREATE</span><h2>Add default</h2></div></div><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><label>Name<input class="input" name="name" maxlength="100" required></label><label>Type<select class="input" name="type"><option value="expense">Expense</option><option value="income">Income</option></select></label><button class="btn btn-primary">Add category</button></form></section><section class="panel"><div class="panel-head"><div><span class="panel-kicker"><?=count($rows)?> DEFAULTS</span><h2>System list</h2></div></div><?php foreach($rows as$c):?><div class="rank-row"><span><?=e($c['name'])?> <small class="muted">· <?=$c['usage_count']?> uses</small></span><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="category_id" value="<?=$c['category_id']?>"><button class="text-button"><?=$c['is_active']?'Disable':'Enable'?></button></form></div><?php endforeach;?></section></div><?php require __DIR__.'/../includes/footer.php';?>